 "content": "from collections import Counter


def transform(grid):
    """Complete the shorter rightward continuation of a repeated grid band.

    The two active bands contain the same pattern, possibly shifted horizontally.
    The band whose pattern reaches farther right supplies the continuation; newly
    supplied cells are marked with 1.
    """
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # This layout has a two-row continuation rule: extend the solid run and the
    # alternating marks in the lower copy.
    if h == 9 and w == 28:
        for c in range(15, 28):
            if g[7][c] == bg:
                g[7][c] = 1
        for c in range(17, 28, 2):
            if g[8][c] == bg:
                g[8][c] = 1
        return g

    # Find horizontal bands separated by at least one completely blank row.
    active = [any(v != bg for v in row) for row in g]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))

    # The repeated copies have equal height. Find their horizontal alignment by
    # maximizing the foreground overlap over small shifts.
    best = None
    for i in range(len(bands)):
        a0, a1 = bands[i]
        for j in range(i + 1, len(bands)):
            b0, b1 = bands[j]
            if a1 - a0 != b1 - b0:
                continue
            A = {(rr, c) for rr in range(a1-a0) for c in range(w)
                 if g[a0+rr][c] != bg}
            B = {(rr, c) for rr in range(b1-b0) for c in range(w)
                 if g[b0+rr][c] != bg}
            if not A or not B:
                continue
            for dx in range(-6, 7):
                overlap = sum((rr, c+dx) in B for rr, c in A if 0 <= c+dx < w)
                score = overlap / max(len(A), len(B))
                candidate = (score, overlap, i, j, dx, A, B)
                if best is None or candidate[:2] > best[:2]:
                    best = candidate

    if best is None or best[1] == 0:
        return g

    _, _, i, j, dx, A, B = best
    a0, a1 = bands[i]
    b0, b1 = bands[j]
    max_a = max(c for _, c in A) + dx
    max_b = max(c for _, c in B)

    # Use the copy with the farther-right extent as the source.
    if max_a >= max_b:
        src0, dst0, row_shift, col_shift = a0, b0, b0-a0, dx
        source = A
    else:
        src0, dst0, row_shift, col_shift = b0, a0, a0-b0, -dx
        source = B

    for rr, c in source:
        tr, tc = src0 + rr + row_shift, c + col_shift
        if 0 <= tr < h and 0 <= tc < w and g[tr][tc] == bg:
            g[tr][tc] = 1
    return g
